<script setup>
import CertificateExpiryBadge from '../components/CertificateExpiryBadge.vue'
import { computed, onMounted, ref } from 'vue'
import { ArrowUpRight, ArrowDownRight, Users, ShoppingBag, CircleDollarSign, CalendarClock, RefreshCw, ChevronRight } from 'lucide-vue-next'
import { api } from '../api'

const data = ref(null), loading = ref(true), error = ref('')
async function load() { loading.value = true; error.value = ''; try { data.value = (await api.get('/dashboard/')).data } catch (e) { error.value = e.message } finally { loading.value = false } }
const trend = computed(() => { const a = Number(data.value?.summary.sales_ytd || 0), b = Number(data.value?.summary.sales_last_ytd || 0); return b ? ((a / b - 1) * 100).toFixed(1) : null })
const chartMax = computed(() => Math.max(...(data.value?.monthly_sales || []).map(i => Number(i.sales)), 1))
const categoryTotal = computed(() => (data.value?.category_sales || []).reduce((s, i) => s + Number(i.sales), 0) || 1)
function money(v, symbol = '$') { return `${symbol}${Number(v || 0).toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }
function short(v) { const n = Number(v || 0); return n >= 10000 ? `${(n / 10000).toFixed(1)}万` : n.toLocaleString() }
onMounted(load)
</script>

<template>
  <div v-if="loading" class="loading"><div class="spinner" /></div>
  <div v-else-if="error" class="panel error-state"><p>{{ error }}</p><button class="btn btn-primary" @click="load"><RefreshCw :size="15" /> 重试</button></div>
  <div v-else-if="data" class="dashboard">
    <div class="welcome"><div><span>今日经营简报</span><h2>把每一笔生意，都变成清晰的增长线索。</h2><p>以下数据来自已关联的客户、订单和财务流水。</p></div><div class="pulse"><i></i>数据已实时同步</div></div>
    <div class="metric-grid">
      <div class="metric-card featured"><div class="metric-top"><span>本年销售额（人民币）</span><div class="metric-icon"><CircleDollarSign :size="18" /></div></div><strong>{{ money(data.summary.sales_ytd, '¥') }}</strong><small v-if="trend" :class="Number(trend) >= 0 ? 'up' : 'down'"><component :is="Number(trend) >= 0 ? ArrowUpRight : ArrowDownRight" :size="13" /> {{ Math.abs(trend) }}% 较去年同期</small><small v-else>去年同期暂无数据</small></div>
      <div class="metric-card"><div class="metric-top"><span>本年订单</span><div class="metric-icon amber"><ShoppingBag :size="18" /></div></div><strong>{{ data.summary.orders_ytd }}</strong><small>平均每单 {{ data.summary.orders_ytd ? money(Number(data.summary.sales_ytd) / data.summary.orders_ytd, '¥') : '¥0' }}</small></div>
      <div class="metric-card"><div class="metric-top"><span>合作中客户</span><div class="metric-icon blue"><Users :size="18" /></div></div><strong>{{ data.summary.active_customers }}</strong><small>客户资产持续沉淀</small></div>
      <div class="metric-card"><div class="metric-top"><span>待跟进</span><div class="metric-icon rose"><CalendarClock :size="18" /></div></div><strong>{{ data.summary.follow_ups_due }}</strong><small :class="{ down: data.summary.follow_ups_due }">今日及逾期事项</small></div>
    </div>

    <section class="panel list-panel certificate-reminders" aria-label="证书到期提醒">
      <div class="panel-title"><div><h3>证书到期提醒</h3><p v-if="data.summary.certificate_attention">需关注 {{ data.summary.certificate_attention }} 个，其中已过期 {{ data.summary.certificate_expired }} 个 · 90 天内到期 {{ data.summary.certificate_expiring }} 个</p><p v-else>当前没有 90 天内到期的证书</p></div><RouterLink to="/product-certificates?expiry=attention">查看全部 <ChevronRight :size="14" /></RouterLink></div>
      <RouterLink v-for="c in data.certificate_alerts || []" :key="c.id" :to="{ path: '/product-certificates', query: { expiry: 'attention', detail: c.id } }" class="follow-item"><div class="grow"><strong>{{ c.product_name }}</strong><small>{{ c.certificate_name }} · {{ c.certificate_no || '无编号' }}</small></div><span>{{ c.expires_on }}</span><CertificateExpiryBadge :certificate="c" /></RouterLink>
    </section>
    <div class="dash-grid">
      <div class="panel chart-panel"><div class="panel-title"><div><h3>销售趋势</h3><p>近 12 个月订单销售额</p></div><span class="legend"><i></i>销售额</span></div>
        <div v-if="data.monthly_sales.length" class="bar-chart"><div v-for="item in data.monthly_sales" :key="item.month" class="bar-slot"><div class="bar-value">{{ short(item.sales) }}</div><div class="bar" :style="{ height: `${Math.max(Number(item.sales) / chartMax * 155, 4)}px` }"><span>{{ item.orders }}单</span></div><label>{{ item.month.slice(5) }}月</label></div></div><div v-else class="empty compact">暂无趋势数据</div>
      </div>
      <div class="panel category-panel"><div class="panel-title"><div><h3>品类表现</h3><p>本年商品分类销售额（仅商品行）</p></div></div>
        <div v-if="data.category_sales.length" class="category-list"><div v-for="(item,index) in data.category_sales" :key="index" class="category-row"><div class="category-meta"><span><i :style="{ background: ['#1d5a50','#e4813e','#6d8ea0','#c49b62','#897aa5'][index%5] }"></i>{{ item.sku__product__category__name || '未分类' }}</span><strong>{{ money(item.sales, '¥') }}</strong></div><div class="progress"><i :style="{ width: `${Number(item.sales)/categoryTotal*100}%`, background: ['#1d5a50','#e4813e','#6d8ea0','#c49b62','#897aa5'][index%5] }"></i></div></div></div><div v-else class="empty compact">暂无品类数据</div>
      </div>
    </div>

    <div class="dash-bottom">
      <div class="panel list-panel"><div class="panel-title"><div><h3>重点客户</h3><p>本年按销售额排序</p></div><RouterLink to="/customers">查看全部 <ChevronRight :size="14" /></RouterLink></div><div class="customer-list"><RouterLink v-for="(c,index) in data.top_customers" :key="c.id" :to="{ path: '/customers', query: { detail: c.id } }" class="customer-item"><span class="rank">{{ String(index+1).padStart(2,'0') }}</span><div class="customer-logo">{{ c.name.slice(0,1) }}</div><div class="grow"><strong>{{ c.name }}</strong><small>{{ c.country || '未填写国家' }} · {{ c.orders }} 个订单</small></div><strong class="amount">{{ money(c.sales, '¥') }}</strong></RouterLink><div v-if="!data.top_customers.length" class="empty compact">暂无客户业绩</div></div></div>
      <div class="panel list-panel"><div class="panel-title"><div><h3>待跟进事项</h3><p>把承诺变成下一步行动</p></div><RouterLink to="/follow-ups?due=true">查看全部 <ChevronRight :size="14" /></RouterLink></div><div><RouterLink v-for="f in data.due_follow_ups" :key="f.id" :to="{ path: '/follow-ups', query: { due: 'true', detail: f.id } }" class="follow-item"><div class="date-box"><strong>{{ f.next_follow_up?.slice(8,10) }}</strong><span>{{ f.next_follow_up?.slice(5,7) }}月</span></div><div class="grow"><strong>{{ f.customer_name }}</strong><small>{{ f.subject }}</small></div><span class="owner">{{ f.owner || '未分配' }}</span></RouterLink><div v-if="!data.due_follow_ups.length" class="empty compact">当前没有待跟进事项</div></div></div>
    </div>
    <div class="cash-strip"><div><span>本年已确认收款（人民币）</span><strong>¥{{ Number(data.summary.receipts_rmb).toLocaleString() }}</strong></div><i></i><div><span>本年已确认支出（人民币）</span><strong>¥{{ Number(data.summary.payments_rmb).toLocaleString() }}</strong></div><i></i><div><span>净现金流</span><strong :class="Number(data.summary.receipts_rmb)-Number(data.summary.payments_rmb)>=0?'positive':'negative'">¥{{ (Number(data.summary.receipts_rmb)-Number(data.summary.payments_rmb)).toLocaleString() }}</strong></div></div>
  </div>
</template>

<style scoped>
